        dlg("e05_c40", "act3", "narrator", "午夜说书人", "舞罢，那月中仙子婉转旋身，纵身跃上石桌，众目睽睽之下竟咔哒一声又变回了那根普通竹筷！三位仙人大笑拍手，鹤发奇客站起身，意犹未尽地望向墙上明月。", gap_after_s=0.22),
