        dlg("e06_c15", "act1", "weird_beggar", "勾魂阴差", "[softly] [eerie] 呵呵，此番考的不是人间功名。到了那座巍峨大殿，秀才自然明白！请上马罢！", gap_after_s=0.24),
        sfx("e06_c16", "act1", "Brisk light horse galloping steadily upward dissolving into rushing high-altitude clouds and solemn distant wind chimes, pure foley, no human voice", duration_seconds=3.0, gap_after_s=0.24),
        dlg("e06_c17", "act1", "scholar_young", "宋焘", "[curious] [whispers] 云雾怎么都在马蹄下头？低头望去，家里那点小小的油灯光亮，竟小得像一粒萤火虫……这究竟要把我带去何处？", stability=0.5, acoustic_space="mental_realm", gap_after_s=0.24),
        dlg("e06_c18", "act1", "narrator", "午夜说书人", "白马四蹄踏雾而行，不多时，银灰苍茫的云海豁然分开，一座比人间皇城还要恢弘肃穆的朱门官署，静静矗立在万丈霞光之中。", gap_after_s=0.28),
        # --- ACT 2: Underworld Imperial Exam & Portraits of Examinees ---
        motif("e06_c19", "act2", "temple_bell_midnight", gap_after_s=0.24, director_note="冥府正殿古钟齐鸣"),
        sfx("e06_c20", "act2", "Massive ancient bronze palace doors booming open slowly with solemn ritual stone chimes ringing across a vast echoing marble courtyard, pure foley, no human voice", duration_seconds=3.0, gap_after_s=0.22),
        dlg("e06_c21", "act2", "narrator", "午夜说书人", "青石丹墀两侧金甲武士肃立，仪仗森严，铜鼎焚着清冽檀香。巍峨正殿之上高坐十余位袍笏端庄、宝相威严的神明，正中那位丹凤眼、卧蚕眉、五绺长髯垂胸，气概贯日，赫然便是伏魔大帝关圣帝君！", gap_after_s=0.26),
        dlg("e06_c22", "act2", "narrator", "午夜说书人", "长廊两翼早已摆好了几十张紫檀书案，数十名来自各地的应试士子按号落座。开考前的一刻，廊下众人神态各异、百态毕露。", gap_after_s=0.22),
        dlg("e06_c23", "act2", "official_snob", "傲慢举人", "[condescending] [whispers] 哼，瞧你这身洗得发白的补丁儒衫，怕是哪家穷酸书生也混进来了！本公子熟背万篇八股范文，连考官最爱看的华丽典故都背得滚瓜烂熟，今日头名非我莫属！", stability=0.0, gap_after_s=0.22),
        dlg("e06_c24", "act2", "scholar_panicked", "胆怯秀才", "[terrified] [whispers] 兄台别吹牛了……你低头瞧瞧咱们脚底下，连影子都没有！正殿上头坐着那位分明是庙里的关帝老爷！咱们怕不是……全都已经死了，在考阴司官职啊！", stability=0.0, gap_after_s=0.24),
        dlg("e06_c25", "act2", "innkeeper_elder", "长山张生", "[calmly] [warmly] 诸位莫要喧哗惊扰圣驾。文章本在胸中赤诚，岂在一身锦绣华服？这位兄台气度沉静，敢问尊姓大名？在下长山张氏，今日能与君同场应试，甚幸。", gap_after_s=0.22),
        dlg("e06_c26", "act2", "scholar_young", "宋焘", "[warmly] 幸会张兄！在下河南宋焘。既入此殿，便当收摄心神，以平生诚意答卷，莫负圣明。", gap_after_s=0.22),
        dlg("e06_c27", "act2", "narrator", "午夜说书人", "话音刚落，那胆怯秀才抖得像筛糠，手里毛笔当啷掉在砚台上。刹那间，玉磬一声清鸣，半空飘落一张雪白考题纸，上面墨迹淋漓，仅有八个大字！", gap_after_s=0.20),
        sfx("e06_c28", "act2", "Clear resonant jade chime ringing once across a vast stone hall followed by dozens of crisp paper sheets settling onto wooden desks, pure foley, no human voice", duration_seconds=2.6, gap_after_s=0.20),
        dlg("e06_c29", "act2", "underworld_judge", "主考神官", "[solemn] 诸生肃静！此次大考不拼华丽辞藻，只问本心正道！考题八字：一人二人，有心无心。限时一炷香，落笔莫迟！", stability=1.0, acoustic_space="vast_hall", gap_after_s=0.26),
        sfx("e06_c30", "act2", "Dozens of calligraphy brushes dipping briskly into inkstones and scratching across crisp xuan paper in hushed cavernous hall tension, pure foley, no human voice", duration_seconds=2.8, gap_after_s=0.22),
        dlg("e06_c31", "act2", "narrator", "午夜说书人", "那傲慢举人皱紧眉头，拼命堆砌四书五经的生僻典故，写得满纸浮夸；身旁众人或咬笔苦思，或冷汗涔涔。唯独宋焘凝望“有心无心”四字沉吟片刻，心头如明镜骤开。", gap_after_s=0.24),
        dlg("e06_c32", "act2", "scholar_young", "宋焘", "[calmly] [whispers] 天地赏罚，贵在诛心而非炫迹。若存沽名钓誉之心行善，善亦近伪；若无害人之心误触过错，恶尚可原……明白了！", stability=0.5, acoustic_space="mental_realm", gap_after_s=0.28),
        # --- ACT 3: The Immortal 16-Character Thesis & Lord Guan's Decree ---
        sfx("e06_c33", "act3", "Crisp stiff exam papers unrolling smoothly across a grand jade desk followed by a resonant wooden brush handle tapping the bench in approval, pure foley, no human voice", duration_seconds=2.6, gap_after_s=0.22),
        dlg("e06_c34", "act3", "narrator", "午夜说书人", "一炷香燃尽，众卷呈上玉案。几位神官先翻看那傲慢举人的长篇大论，不由纷纷皱眉，当场将那卷子轻掷一旁。", gap_after_s=0.20),
        dlg("e06_c35", "act3", "underworld_judge", "主考神官", "[coldly] [solemn] 哼，满纸阿谀浮词，尽是市井求荣的匠气，全无半点真心！撤下去！", stability=1.0, acoustic_space="vast_hall", gap_after_s=0.22),
        dlg("e06_c36", "act3", "narrator", "午夜说书人", "可待神官翻开宋焘那张笔势清峻的考卷，满殿神明齐齐动容！连正中端坐的关圣帝君也抚须朗笑，拍案大赞！", gap_after_s=0.20),
        dlg("e06_c37", "act3", "underworld_judge", "主考神官", "[dramatically] [solemn] 妙哉！诸卷皆落俗套，唯宋焘一卷字字如刀、直指天心！且听宋生卷中破题十六字——", stability=1.0, acoustic_space="vast_hall", gap_after_s=0.20),
        dlg("e06_c38", "act3", "scholar_young", "宋焘", "[solemn] 有心为善，虽善不赏；无心为恶，虽恶不罚。", stability=0.5, acoustic_space="vast_hall", gap_after_s=0.36),
        dlg("e06_c39", "act3", "celestial_voice", "关圣帝君", "[solemn] 善哉！这十六个字，道尽三界赏罚之大公！世人若为求功名、博虚誉而刻意施舍，不过是把仁义当作市井买卖，虽善何赏？若本心纯良却因仓促无心而犯错，心存敬畏，虽恶何罚！", stability=1.0, acoustic_space="vast_hall", gap_after_s=0.28),
        dlg("e06_c40", "act3", "celestial_voice", "关圣帝君", "[dramatically] [solemn] 河南城隍一缺久悬，正待纯良刚正之士镇守一方！宋焘听旨——本君即刻敕封你为河南城隍，受此印绶，即刻赴任！", stability=1.0, acoustic_space="vast_hall", gap_after_s=0.24),
        sfx("e06_c41", "act3", "Deep ceremonial bronze palace bells and solemn ritual drums resonating slowly across a vast marble hall, pure foley, no human voice", duration_seconds=2.8, gap_after_s=0.22),
        dlg("e06_c42", "act3", "official_snob", "傲慢举人", "[gasps] [whispers] 天呐……这破衫寒士竟凭短短十六个字夺了魁首，还被帝君亲敕为河南城隍！我那满篇华丽辞藻，竟连给人家磨墨都不配……", stability=0.0, gap_after_s=0.22),
        dlg("e06_c43", "act3", "innkeeper_elder", "长山张生", "[warmly] [calmly] 宋兄大才，实至名归！恭喜宋兄得列仙班、造福河南黎民！", gap_after_s=0.28),
        # --- ACT 4: Tearful Plea for Mother & Farewell to Scholar Zhang ---
        dlg("e06_c44", "act4", "narrator", "午夜说书人", "满殿神明与同场士子纷纷拱手道贺！可“城隍”二字落进宋焘耳中，却宛如一记晴天霹雳——城隍乃阴司正神，敕封城隍，便意味着自己此刻已经阳寿告终、魂离人间！", gap_after_s=0.24),
        dlg("e06_c45", "act4", "seductive_ghost", "宋母", "[softly] [warmly] 焘儿，天凉了，把参汤趁热喝了吧……娘身子骨还硬朗着呢，熬得住……", stability=0.5, acoustic_space="memory_echo", gap_after_s=0.26),
        sfx("e06_c46", "act4", "Heavy muffled thud of knees dropping squarely onto polished white marble palace steps inside a hushed solemn hall, pure foley, no human voice", duration_seconds=2.2, gap_after_s=0.20),
        dlg("e06_c47", "act4", "narrator", "午夜说书人", "老母灯下端药缝衣的瘦弱背影猛然撞进心头，宋焘泪如雨下，不顾仪仗威严，扑通跪伏在白玉丹墀下，磕头泣血！", gap_after_s=0.20),
        dlg("e06_c48", "act4", "scholar_young", "宋焘", "[crying] [desperately] 帝君厚恩，草民万死岂敢推辞！只是家中老母年逾七旬，守寡半生将弟子拉扯成人，膝下更无旁人依靠！弟子若今日赴任，老母孤苦无依，寒冬谁替她添炭，百年之后谁替她送终？", stability=0.0, acoustic_space="vast_hall", gap_after_s=0.26),
        dlg("e06_c49", "act4", "scholar_young", "宋焘", "[crying] [desperately] 求帝君开一线天恩，容弟子暂返阳间侍奉老母终老，待送母入土之日，弟子再甘心赴任，绝无半分怨言！", stability=0.0, acoustic_space="vast_hall", gap_after_s=0.28),
        dlg("e06_c50", "act4", "narrator", "午夜说书人", "大殿瞬间安静得落针可闻。正中关圣帝君神色微动，缓缓颔首，挥袖示意身旁主考神官当庭查检生死薄籍。", gap_after_s=0.22),
        sfx("e06_c51", "act4", "Heavy thick parchment pages of an ancient leather-bound ledger turning decisively across a quiet echoing marble hall, pure foley, no human voice", duration_seconds=2.6, gap_after_s=0.20),
        dlg("e06_c52", "act4", "underworld_judge", "主考神官", "[solemn] [calmly] 启禀帝君，查得宋生老母命籍，阳寿尚余九年整。", stability=1.0, acoustic_space="vast_hall", gap_after_s=0.22),
        dlg("e06_c53", "act4", "narrator", "午夜说书人", "众神官低声议论，唯恐河南城隍悬缺九载无人执掌。就在此时，殿前神明目光一转，望向了廊下名列第二的青衫士子——长山县张秀才。", gap_after_s=0.22),
        dlg("e06_c54", "act4", "celestial_voice", "关圣帝君", "[solemn] 忠孝乃立身之本，岂可令大孝之人抱憾？着长山张生暂署河南城隍九载！宋焘，你且还阳尽孝，九年之后，天马玉辇再来相迎！", stability=1.0, acoustic_space="vast_hall", gap_after_s=0.30),
        dlg("e06_c55", "act4", "narrator", "午夜说书人", "宋焘破涕为笑，连叩三首谢恩，起身退至云雾缭绕的白玉长廊，远远迎上刚刚领了署理官印的长山张生，深深作揖到地。", gap_after_s=0.22),
        dlg("e06_c56", "act4", "scholar_young", "宋焘", "[warmly] [solemn] 张兄大德！因小弟私情累兄台先行奔波九载，宋焘铭感五内！待小弟还阳之后，定往长山拜谢兄台高义！", gap_after_s=0.24),
        dlg("e06_c57", "act4", "innkeeper_elder", "长山张生", "[warmly] [softly] 宋兄快请起，莫要多礼！在下长山人氏，忝居榜眼，能替兄台这等大孝君子看顾九年河南香火，实乃生平幸事！", acoustic_space="memory_echo", gap_after_s=0.24),
        dlg("e06_c58", "act4", "innkeeper_elder", "长山张生", "[warmly] [calmly] 阳间尘缘难得，灯火易冷，兄台快回去陪老太太吃顿热饭吧。九年之后秋风再起，咱们再把这枚大印亲手交割——珍重！", acoustic_space="memory_echo", gap_after_s=0.32),
        # --- ACT 5: Awakening, Verifying Zhang & Nine Years Later ---
        sfx("e06_c59", "act5", "Muted frantic knocking from inside a sealed pine wooden coffin followed by the heavy coffin lid sliding open and ceramic offering bowls rattling sharply onto stone floor, pure foley, no human voice", duration_seconds=3.0, gap_after_s=0.22),
        dlg("e06_c60", "act5", "narrator", "午夜说书人", "白玉宫阙在云雾里轰然散尽。宋焘胸口猛地一热，倏然睁开了眼睛——四周竟黑漆漆一片，鼻尖满是浓烈的松木香！他已经“断气”整整三日，家人刚刚将遗体入殓棺中，正准备落钉封棺，忽听棺里传来拍板声！", gap_after_s=0.24),
        dlg("e06_c61", "act5", "scholar_panicked", "宋家小厮", "[terrified] [excited] 老太太！快住手别钉棺材！少爷在里头拍板子呢！少爷坐起来了！少爷活过来了！", stability=0.0, gap_after_s=0.20),
        dlg("e06_c62", "act5", "seductive_ghost", "宋母", "[crying] [warmly] 焘儿！我的儿啊！苍天有眼，你真的回来了！娘还以为这辈子再也见不着你了！", stability=0.5, gap_after_s=0.22),
        dlg("e06_c63", "act5", "scholar_young", "宋焘", "[warmly] [softly] 娘别哭，孩儿回来了，还要再陪您老人家整整九年呢。", gap_after_s=0.24),
        dlg("e06_c64", "act5", "narrator", "午夜说书人", "宋焘病体竟自此一日千里地痊愈。他心中始终放不下冥府廊下那位义士，刚能下床，便立刻写信差遣小厮骑快马赶往几百里外的长山县，暗中打听是否真有这么一位张秀才。", gap_after_s=0.24),
        sfx("e06_c65", "act5", "Hurried horse hooves stopping at a village courtyard followed by heavy wooden door pushing open and quick boots striding across stone, pure foley, no human voice", duration_seconds=2.6, gap_after_s=0.20),
        dlg("e06_c66", "act5", "scholar_panicked", "宋家小厮", "[rushed] [curious] 少爷！太神奇了！小的跑遍长山县，果真打听到一位品行端方、人人称赞的张秀才！乡邻们都说，张秀才平时身强体壮，偏偏就在少爷您昏迷赴考的那一天、同一个时辰，端坐在书房里笑着无疾而终了！", stability=0.0, gap_after_s=0.26),
        sfx("e06_c67", "act5", "Three thin sandalwood incense sticks planted gently into dry ash inside an ancient brass censer in a quiet humble courtyard, pure foley, no human voice", duration_seconds=2.4, gap_after_s=0.20),
        dlg("e06_c68", "act5", "narrator", "午夜说书人", "听完回报，宋焘默然良久，亲手点起三炷清香，面向长山方向深深三拜，眼角泛起温热泪光。", gap_after_s=0.20),
        dlg("e06_c69", "act5", "scholar_young", "宋焘", "[sighs] [solemn] 苍天不欺……张兄果然先我一步赴任河南去了。从今日起，这一寸光阴，皆是天恩与张兄借予我的，我绝不虚度半日。", gap_after_s=0.28),
        sfx("e06_c70", "act5", "Gentle autumn wind sweeping dry crisp leaves steadily across a serene quiet courtyard with soft distant wind chimes marking passing seasons, pure foley, no human voice", duration_seconds=3.0, gap_after_s=0.24),
        dlg("e06_c71", "act5", "narrator", "午夜说书人", "此后整整九年，宋焘绝迹功名场，不曾远游一步。晨起煎粥奉茶，冬夜温被添炭，陪着老母度过了九度春花秋月。第九年深秋，霜降时节，银丝满头的老太太在病榻上轻轻握住了儿子的手。", gap_after_s=0.24),
        dlg("e06_c72", "act5", "seductive_ghost", "宋母", "[softly] [warmly] 焘儿，这九年有你在身边日日照拂，娘心里甜得很，一点苦也没吃过。娘累了，先睡一会儿，你往后要好好照顾自己……", stability=0.5, gap_after_s=0.26),
        dlg("e06_c73", "act5", "narrator", "午夜说书人", "老太太含笑合眼，无病无痛，安详寿终。宋焘忍泪操办完丧事，将老母风风光光安葬入土。回到冷清的小院，他烧水沐浴，换上一身崭新洁净的青衫儒服，拉住泣不成声的老仆小厮，微笑着最后交代了几句家事。", gap_after_s=0.24),
        dlg("e06_c74", "act5", "scholar_panicked", "宋家小厮", "[crying] [desperately] 少爷……老太太刚走，您身子明明好端端的，怎么突然换上新衣说要远行呢？小的舍不得您啊！", stability=0.0, gap_after_s=0.22),
        dlg("e06_c75", "act5", "scholar_young", "宋焘", "[warmly] [calmly] 傻孩子，莫哭。人生聚散早有定数，我赴的不是苦差，是九年前便许下的君子之约。你替我看好老太太的坟茔，便是最好的报答。", gap_after_s=0.26),
        sfx("e06_c76", "act5", "Serene crisp hooves of a white horse and delicate solemn bronze bridle bells approaching calmly down an autumn dusk street before ascending softly into mist, pure foley, no human voice", duration_seconds=3.4, gap_after_s=0.24),
        dlg("e06_c77", "act5", "narrator", "午夜说书人", "暮色四合，院外空巷里，远远飘来了九年前那个夜晚无比熟悉的清脆马蹄与铜铃声——车马仪仗，如期而至。宋焘独自步入静室端坐定神。", gap_after_s=0.24),
        dlg("e06_c78", "act5", "scholar_young", "宋焘", "[calmly] [warmly] 母亲已安，九年之约到了。张兄，久等了。", gap_after_s=0.34),
        dlg("e06_c79", "act5", "narrator", "午夜说书人", "话音落下，宋焘含笑阖目，安然羽化。传说那夜城中无数百姓仰望夜空，隐约看见一队金灯仪仗乘着秋风浩浩荡荡往南而去，满城皆闻幽幽异香。", gap_after_s=0.30),
        motif("e06_c80", "act5", "temple_bell_midnight", gap_after_s=0.38, director_note="第一季收官长钟余韵"),
